function eventmenu_install_detect_url():string{$c=trim((string)env('APP_URL',''));if($c!=='')return rtrim($c,'/');$fp=strtolower(trim(explode(',',(string)($_SERVER['HTTP_X_FORWARDED_PROTO']??''))[0]??''));$https=(!empty($_SERVER['HTTPS'])&&strtolower((string)$_SERVER['HTTPS'])!=='off')||$fp==='https';$h=trim((string)($_SERVER['HTTP_HOST']??'localhost'));if(!preg_match('/^[A-Za-z0-9.\-:\[\]]+$/',$h))$h='localhost';return($https?'https':'http').'://'.$h;}
function eventmenu_install_driver(string $v):string{$v=strtolower(trim($v));if($v==='mariadb')$v='mysql';if(!in_array($v,['sqlite','mysql'],true))throw new RuntimeException('Escolha SQLite ou MySQL/MariaDB.');return$v;}
function eventmenu_install_build_env(string $url,string $driver,array $in):array{$url=rtrim(trim($url),'/');if(!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('URL inválida.');$scheme=strtolower((string)parse_url($url,PHP_URL_SCHEME));$host=strtolower((string)parse_url($url,PHP_URL_HOST));if($scheme!=='https'&&!in_array($host,['localhost','127.0.0.1','::1'],true))throw new RuntimeException('HTTPS é obrigatório em produção.');$driver=eventmenu_install_driver($driver);$v=['APP_NAME'=>'EventMenu Premium','APP_ENV'=>'production','APP_DEBUG'=>'false','APP_URL'=>$url,'APP_BASE_PATH'=>app_base_path(),'APP_KEY'=>Security::randomKey(32),'CRON_SECRET'=>Security::randomKey(32),'DB_CONNECTION'=>$driver,'DB_SQLITE_PATH'=>'storage/eventmenu.sqlite','DB_SQLITE_WAL'=>'auto','DB_HOST'=>'127.0.0.1','DB_PORT'=>'3306','DB_DATABASE'=>'eventmenu','DB_USERNAME'=>'root','DB_PASSWORD'=>'','SESSION_NAME'=>'eventmenu_session','SESSION_SECURE'=>$scheme==='https'?'true':'false','PAYMENT_CURRENCY'=>'BRL'];if($driver==='mysql'){$v['DB_HOST']=trim((string)($in['db_host']??''));$v['DB_PORT']=(string)(int)($in['db_port']??3306);$v['DB_DATABASE']=trim((string)($in['db_database']??''));$v['DB_USERNAME']=trim((string)($in['db_username']??''));$v['DB_PASSWORD']=(string)($in['db_password']??'');if($v['DB_HOST']===''||$v['DB_DATABASE']===''||$v['DB_USERNAME']==='')throw new RuntimeException('Preencha os dados do MySQL.');}return$v;}
function eventmenu_install_write_env(string $p,array $v):void{$l=[];foreach($v as$k=>$x){$x=$x===''?'':(preg_match('/^[A-Za-z0-9_\.\-\/:]+$/',$x)?$x:'"'.addcslashes($x,"\\\"").'"');$l[]=$k.'='.$x;}if(file_put_contents($p,implode("\n",$l)."\n",LOCK_EX)===false)throw new RuntimeException('Falha ao criar .env.');@chmod($p,0640);eventmenu_install_runtime_env($v);}
$pre=['PHP 8.2+'=>version_compare(PHP_VERSION,'8.2.0','>='),'Dependências PHP'=>is_file($root.'/vendor/autoload.php'),'Storage gravável'=>(is_dir($storagePath)&&is_writable($storagePath))||(!is_dir($storagePath)&&is_writable($root)),'.env gravável'=>is_file($envPath)?is_writable($envPath):is_writable($root)];$preOk=!in_array(false,$pre,true);$sqlite=in_array('sqlite',PDO::getAvailableDrivers(),true)&&is_readable($root.'/database/sqlite/schema.sql');$mysql=in_array('mysql',PDO::getAvailableDrivers(),true)&&is_readable($root.'/database/schema.sql');if(is_file($lock)){http_response_code(403);exit('EventMenu já instalado.');}$error=null;$success=false;$done='';$url=eventmenu_install_detect_url();
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Security::validateCsrf($_POST['_csrf']??null))throw new RuntimeException('Sessão expirada.');if(!$preOk)throw new RuntimeException('Servidor não atende aos requisitos.');$driver=eventmenu_install_driver((string)($_POST['db_driver']??'sqlite'));if($driver==='sqlite'&&!$sqlite)throw new RuntimeException('SQLite indisponível.');if($driver==='mysql'&&!$mysql)throw new RuntimeException('MySQL indisponível.');if(!is_dir($storagePath)&&!mkdir($storagePath,0775,true)&&!is_dir($storagePath))throw new RuntimeException('Falha ao criar storage.');$env=eventmenu_install_build_env((string)($_POST['app_url']??$url),$driver,$_POST);eventmenu_install_write_env($envPath,$env);$pdo=Database::connection();$schema=file_get_contents(Database::schemaPath($pdo));if($schema===false)throw new RuntimeException('Schema não encontrado.');$pdo->exec($schema);Migrator::run($pdo);$email=mb_strtolower(trim((string)($_POST['email']??'juliodelgadogui@gmail.com')));$name=trim((string)($_POST['name']??'Julio Delgado'));$pass=(string)($_POST['password']??'1');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('E-mail inválido.');if(strlen($pass)<1||strlen($pass)>200)throw new RuntimeException('Senha inválida.');$q=$pdo->prepare('SELECT id FROM users WHERE role=? LIMIT 1');$q->execute(['super_admin']);if($q->fetchColumn())throw new RuntimeException('Já existe Super ADM neste banco.');$i=$pdo->prepare("INSERT INTO users (tenant_id,name,email,password_hash,role,status) VALUES (NULL,?,?,?,'super_admin','active')");$i->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);JcLancheDemoSeeder::run($pdo);if(file_put_contents($lock,date(DATE_ATOM),LOCK_EX)===false)throw new RuntimeException('Banco criado, mas falhou ao gravar lock.');@chmod($lock,0640);$done=$driver;$success=true;}catch(Throwable$e){$error=$e->getMessage();}}
$cronScript=is_file($root.'/cron.php')?$root.'/cron.php':$root.'/public/cron.php';$cron='* * * * * php '.escapeshellarg($cronScript).' >/dev/null 2>&1';
