t name="db_password" type="password"></label></div><h2>Super ADM</h2><label>Nome<input name="name" value="Julio Delgado" required></label><label>E-mail<input name="email" type="email" value="juliodelgadogui@gmail.com" required></label><label>Senha<input name="password" type="password" minlength="1" maxlength="200" value="1" required><small>Senha curta permitida. Troque antes de produção.</small></label><button class="primary" type="submit">Instalar EventMenu + JC Lanche</button></form><script>const b=document.getElementById('mysql'),r=[...document.querySelectorAll('[name=db_driver]')];function s(){b.hidden=r.find(x=>x.checked)?.value!=='mysql'}r.forEach(x=>x.onchange=s);s()</script><?php endif;?><?php endif;?></main></body></html>